#requires -version 5.1
param([switch]$OwnTempSelfTest)
$ErrorActionPreference='Stop'
$projectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));Set-Location -LiteralPath $projectRoot
Import-Module (Join-Path $projectRoot 'app\CleanData\TempCleanup.psm1') -DisableNameChecking
$checks=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Value,[string]$Message);if(-not$Value){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Action);try{&$Action;$checks.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$checks.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
function Reject {param([scriptblock]$Action);$failed=$false;try{&$Action|Out-Null}catch{$failed=$true};Assert $failed 'Expected rejection'}
$elevated=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
Check 'Narrow policy; no recursion, elevation or automatic permanent cleanup' {$p=Get-MCTempPolicy;Assert ($p.capability-eq'ReviewedTopLevelOwnTemp'-and-not$p.allowElevation-and-not$p.recursive-and$p.permanentRequiresTwoSteps-and($p.minimumDays-join',')-eq'7,7,3') 'Unexpected Temp policy'}
Check 'Closed/unknown sessions cannot approve or execute' {Reject {Get-MCTempPlan 'unknown'};Reject {Review-MCTempPlan 'unknown' 'ctx' @('x')};Reject {Confirm-MCTempPlan 'unknown' 'ctx' $true};Reject {Invoke-MCTempPlan 'unknown' 'ctx'}}
Check 'Returned policy does not grant permission through a GUI flag' {$p=Get-MCTempPolicy;$p.allowElevation=$true;Assert (-not(Get-MCTempPolicy).allowElevation) 'Policy object leaked mutation';Reject {Invoke-MCTempPlan 'gui-approved' 'ctx'}}
Check 'Native journal rejects malformed identifiers' {Reject {New-Object MemoryClear.Storage.FileInventory+TempLedger($projectRoot,'../outside')}}
Check 'Journal create-new, flush and no overwrite' {$id=[guid]::NewGuid().ToString('N');$log=New-Object MemoryClear.Storage.FileInventory+TempLedger($projectRoot,$id);try{$log.Append('{"Kind":"TestOnly","Deleted":false}');Reject {New-Object MemoryClear.Storage.FileInventory+TempLedger($projectRoot,$id)}}finally{$log.Dispose()};$f=Join-Path $projectRoot ('.data\temp-operation-'+$id+'.jsonl');Assert ([IO.File]::ReadAllText($f).Contains('TestOnly')) 'No journal trace'}
if($elevated){Check 'Elevated host fails closed before scanning or deleting user Temp' {Reject {[MemoryClear.Storage.FileInventory]::OwnTempRoot()};Reject {New-MCTempPlan -Context 'elevated-test'}}}
if($OwnTempSelfTest){
    if($elevated){throw 'OwnTempSelfTest must run from a normal, non-administrator PowerShell. No user files were created or deleted.'}
    # Operator opt-in: only these newly created exact filenames are mutation targets.
    $root=[MemoryClear.Storage.FileInventory]::OwnTempRoot();$prefix='memoryclear-qa-'+[guid]::NewGuid().ToString('N');$ctx=[guid]::NewGuid().ToString('N');$created=New-Object 'System.Collections.Generic.List[string]'
    function OwnFile {param([string]$Suffix,[int]$Days=10);$p=Join-Path $root ($prefix+'-'+$Suffix);[IO.File]::WriteAllText($p,'Disposable self-test only: '+$Suffix);[IO.File]::SetLastWriteTimeUtc($p,[DateTime]::UtcNow.AddDays(-$Days));$created.Add($p);$p}
    $old=OwnFile 'old.tmp';$locked=OwnFile 'locked.log';$recent=OwnFile 'recent.tmp' 0;$unknown=OwnFile 'unknown.bin';$changed=OwnFile 'changed.tmp';$cancelled=OwnFile 'cancelled.tmp'
    $held=$null
    try{
        Check 'Native Temp rejects workspace paths, recent and unknown file types' {foreach($p in @($recent,$unknown)){Reject {[MemoryClear.Storage.FileInventory]::ValidateOwnTemp([MemoryClear.Storage.FileInventory]::Snapshot($p,$root),7)}};$f=Join-Path $projectRoot 'app\temp-cleanup-policy.json';Reject {[MemoryClear.Storage.FileInventory]::ValidateOwnTemp([MemoryClear.Storage.FileInventory]::Snapshot($f,$projectRoot),7)}}
        Check 'Selective plan reads only requested QA targets and returns detached rows' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($old,$recent,$unknown);Assert ($plan.Items.Count-eq1-and$plan.Items[0].Path-eq$old) 'Unexpected targets';$plan.Items[0].Path=$unknown;Assert ((Get-MCTempPlan $plan.Id).Items[0].Path-eq$old) 'Session mutation';Close-MCTempPlan $plan.Id}
        Check 'Two-step review and no execution from checkboxes alone' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($old);Reject {Confirm-MCTempPlan $plan.Id $ctx $true};Reject {Invoke-MCTempPlan $plan.Id $ctx};Reject {Review-MCTempPlan $plan.Id $ctx @('wrong')};$next=Review-MCTempPlan $plan.Id $ctx @($plan.Items[0].Id);Assert ($next.Stage-eq'Confirm') 'No second step';Reject {Confirm-MCTempPlan $plan.Id $ctx $false};Close-MCTempPlan $plan.Id}
        Check 'Exact own QA file permanent delete, durable trace and no replay' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($old);Review-MCTempPlan $plan.Id $ctx @($plan.Items[0].Id)|Out-Null;Confirm-MCTempPlan $plan.Id $ctx $true;$r=Invoke-MCTempPlan $plan.Id $ctx;Assert ($r.Status-eq'Completed'-and$r.Items[0].Status-eq'Deleted'-and-not[IO.File]::Exists($old)-and[IO.File]::ReadAllText($r.Journal).Contains('Committed')-and[IO.File]::ReadAllText($r.Journal).Contains('Outcome')) 'Delete not proven';Reject {Invoke-MCTempPlan $plan.Id $ctx};Close-MCTempPlan $plan.Id}
        Check 'Changed file content after review is retained' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($changed);Review-MCTempPlan $plan.Id $ctx @($plan.Items[0].Id)|Out-Null;Confirm-MCTempPlan $plan.Id $ctx $true;[IO.File]::WriteAllText($changed,'Changed QA bytes');[IO.File]::SetLastWriteTimeUtc($changed,[DateTime]::FromFileTimeUtc($plan.Items[0].Snapshot.LastWriteFileTime));$r=Invoke-MCTempPlan $plan.Id $ctx;Assert ($r.Status-eq'Partial'-and[IO.File]::Exists($changed)) 'Changed file removed';Close-MCTempPlan $plan.Id}
        Check 'Locked file after approval is retained' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($locked);Review-MCTempPlan $plan.Id $ctx @($plan.Items[0].Id)|Out-Null;Confirm-MCTempPlan $plan.Id $ctx $true;$held=[IO.File]::Open($locked,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$r=Invoke-MCTempPlan $plan.Id $ctx;Assert ($r.Status-eq'Partial'-and[IO.File]::Exists($locked)-and[IO.File]::ReadAllText($r.Journal).Contains('Skipped')) 'Locked file removed'}finally{$held.Dispose();$held=$null};Close-MCTempPlan $plan.Id}
        Check 'Cancellation before execution retains QA file' {$plan=New-MCTempPlan -Context $ctx -CandidatePaths @($cancelled);Review-MCTempPlan $plan.Id $ctx @($plan.Items[0].Id)|Out-Null;Confirm-MCTempPlan $plan.Id $ctx $true;$token=New-Object Threading.CancellationTokenSource;try{$token.Cancel();$r=Invoke-MCTempPlan $plan.Id $ctx -CancellationToken $token.Token;Assert ($r.Status-eq'Cancelled'-and$r.Processed-eq0-and[IO.File]::Exists($cancelled)) 'Cancel failed'}finally{$token.Dispose()};Close-MCTempPlan $plan.Id}
    }finally{if($held){$held.Dispose()};foreach($id in @([MemoryClear.Storage.OperationSessionStore]::TempSessions.Keys)){Close-MCTempPlan $id}}
    # Retain remaining QA files as evidence; never recursively clean Temp.
}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Elevated=$elevated;OwnTempSelfTestExecuted=[bool]$OwnTempSelfTest;Passed=@($checks|Where-Object{$_.Passed}).Count;Failed=@($checks|Where-Object{-not$_.Passed}).Count;Checks=$checks.ToArray();Scope=if($OwnTempSelfTest){'Only exact freshly created own QA Temp files; no existing user files mutated'}else{'Policy/session/journal/elevated guards only; real Temp delete path unverified'};RemainingOwnQaFiles=if($OwnTempSelfTest){$created.ToArray()}else{@()}}
$report|ConvertTo-Json -Depth 7|Set-Content (Join-Path $projectRoot ('docs\verification\'+$(if($OwnTempSelfTest){'temp-cleanup-tests.json'}else{'temp-cleanup-guard-tests.json'}))) -Encoding UTF8
Write-Host ('Temp checks: '+$report.Passed+' passed, '+$report.Failed+' failed; own Temp mutation executed='+$OwnTempSelfTest)
if($report.Failed){$report.Checks|Where-Object{-not$_.Passed}|Format-List;exit 1}
